  const serenity = Number(mood.serenity || 0);
  const wrath = Number(mood.wrath || 0);
  const hunger = Number(mood.hunger || 0);
  const sorrow = Number(mood.sorrow || 0);
  return (serenity * 1.7) - (wrath * 2.2) - (hunger * 0.25) - (sorrow * 0.1);
